const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const california = ee.FeatureCollection("TIGER/2018/States")
    .filter(ee.Filter.eq('NAME', 'California'))
    .geometry();

  const startDate1 = '2012-08-01';
  const endDate1 = '2012-08-31';
  const startDate2 = '2017-04-01';
  const endDate2 = '2017-04-30';

  // 2. Data Acquisition
  // Using NASA GLDAS-2.1: Noah Land Surface Model as it covers the required dates.
  // Band 'SoilMoi0_10cm_inst' represents Soil moisture (0-10 cm below surface) in kg/m^2.
  const dataset = ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H')
    .select('SoilMoi0_10cm_inst');

  const col1 = dataset.filterDate(startDate1, endDate1);
  const col2 = dataset.filterDate(startDate2, endDate2);

  // 3. Data Availability Check
  const count1 = col1.size().getInfo();
  const count2 = col2.size().getInfo();

  if (count1 === 0 || count2 === 0) {
    console.log(`Image count for Aug 2012: ${count1}`);
    console.log(`Image count for Apr 2017: ${count2}`);
    console.log("Empty Collection: No images found for one or both periods.");
    console.log("C1");
    return;
  }

  // 4. Processing and Calculation
  const image1 = col1.mean().clip(california);
  const image2 = col2.mean().clip(california);

  // Reducer to get both mean and count
  const reducers = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = image1.reduceRegion({
    reducer: reducers,
    geometry: california,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = image2.reduceRegion({
    reducer: reducers,
    geometry: california,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1['SoilMoi0_10cm_inst_mean'];
  const pixels1 = stats1['SoilMoi0_10cm_inst_count'];

  const mean2 = stats2['SoilMoi0_10cm_inst_mean'];
  const pixels2 = stats2['SoilMoi0_10cm_inst_count'];

  // 5. Validation and Final Answer
  console.log(`Aug 2012 Avg Soil Moisture (kg/m^2): ${mean1 ? mean1.toFixed(2) : 'N/A'}`);
  console.log(`Aug 2012 Valid Pixel Count: ${pixels1}`);
  console.log(`Apr 2017 Avg Soil Moisture (kg/m^2): ${mean2 ? mean2.toFixed(2) : 'N/A'}`);
  console.log(`Apr 2017 Valid Pixel Count: ${pixels2}`);

  if (pixels1 === 0 || pixels2 === 0) {
    console.log("No valid pixels found after processing for one or both periods.");
    console.log("C2");
    return;
  }

  if (mean1 === null || mean2 === null || mean1 === undefined || mean2 === undefined) {
      console.log("Calculation failed, result is null or undefined.");
      console.log("C3");
      return;
  }

  if (mean2 > mean1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
